      try{let data=JSON.parse(m[2]);console.log(JSON.stringify({script:name,bytes:m[2].length,shape:shape(data)}));}
      catch(e){console.log(JSON.stringify({script:name,bytes:m[2].length,parse_error:String(e),head:m[2].slice(0,100)}));}
    }
    break;
  }
}
})().catch(e=>{console.error(String(e));process.exitCode=1});
